"use client";

import { createContext, useContext, useState, useEffect, ReactNode } from "react";

// Medal Definitions
export const MEDALS = {
    ROOKIE_RECRUIT: {
        id: "rookie_recruit",
        name: "Rookie Recruit",
        description: "Welcome to the battlefield, soldier.",
        icon: "🎖️"
    },
    IRON_ADDICT: {
        id: "iron_addict",
        name: "Iron Addict",
        description: "Visited 7 days consecutively.",
        icon: "🏆"
    },
    DIET_TACTICIAN: {
        id: "diet_tactician",
        name: "Diet Tactician",
        description: "Generated a tactical diet plan.",
        icon: "🍽️"
    },
    CALCULATOR_ELITE: {
        id: "calculator_elite",
        name: "Calculator Elite",
        description: "Used the fitness calculators.",
        icon: "📊"
    }
};

type MedalId = keyof typeof MEDALS;

interface GamificationContextType {
    medals: MedalId[];
    visitStreak: number;
    awardMedal: (medalId: MedalId) => void;
    hasMedal: (medalId: MedalId) => boolean;
}

const GamificationContext = createContext<GamificationContextType | null>(null);

export function GamificationProvider({ children }: { children: ReactNode }) {
    const [medals, setMedals] = useState<MedalId[]>([]);
    const [visitStreak, setVisitStreak] = useState(0);
    const [_isLoaded, setIsLoaded] = useState(false);

    // Load from localStorage on mount
    useEffect(() => {
        if (typeof window === "undefined") return;

        const storedMedals = localStorage.getItem("brofit_medals");
        const storedStreak = localStorage.getItem("brofit_streak");
        const lastVisit = localStorage.getItem("brofit_last_visit");

        let currentMedals: MedalId[] = storedMedals ? JSON.parse(storedMedals) : [];
        let currentStreak = storedStreak ? parseInt(storedStreak) : 0;

        // Check visit streak
        const today = new Date().toDateString();
        if (lastVisit) {
            const lastDate = new Date(lastVisit);
            const diffDays = Math.floor((Date.now() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

            if (diffDays === 1) {
                // Consecutive day visit
                currentStreak += 1;
            } else if (diffDays > 1) {
                // Streak broken
                currentStreak = 1;
            }
            // If diffDays === 0, same day, don't increment
        } else {
            // First ever visit
            currentStreak = 1;
        }

        // Award Rookie Recruit on first visit
        if (!currentMedals.includes("ROOKIE_RECRUIT")) {
            currentMedals = [...currentMedals, "ROOKIE_RECRUIT"];
        }

        // Award Iron Addict for 7 day streak
        if (currentStreak >= 7 && !currentMedals.includes("IRON_ADDICT")) {
            currentMedals = [...currentMedals, "IRON_ADDICT"];
        }

        // Save state
        localStorage.setItem("brofit_medals", JSON.stringify(currentMedals));
        localStorage.setItem("brofit_streak", currentStreak.toString());
        localStorage.setItem("brofit_last_visit", today);

        setMedals(currentMedals);
        setVisitStreak(currentStreak);
        setIsLoaded(true);
    }, []);

    const awardMedal = (medalId: MedalId) => {
        if (!medals.includes(medalId)) {
            const newMedals = [...medals, medalId];
            setMedals(newMedals);
            localStorage.setItem("brofit_medals", JSON.stringify(newMedals));
        }
    };

    const hasMedal = (medalId: MedalId) => medals.includes(medalId);

    // Render Provider even if not loaded (with initial values), or handle loading state differently if needed.
    // Ideally, we should render children always.
    // If we simply return children when !isLoaded, context users will crash.
    // So we MUST return Provider.

    return (
        <GamificationContext.Provider value={{ medals, visitStreak, awardMedal, hasMedal }}>
            {children}
        </GamificationContext.Provider>
    );
}

export function useGamification() {
    const context = useContext(GamificationContext);
    if (!context) {
        throw new Error("useGamification must be used within a GamificationProvider");
    }
    return context;
}

"use client";

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence, useDragControls, PanInfo } from "framer-motion";
import { Cpu, X, Send, Dumbbell, Utensils, Zap, Languages, LogIn, User } from "lucide-react";
import { useUserAuth } from "@/lib/user-auth-context";
import dynamic from "next/dynamic";

// Lazy load LoginModal to avoid SSR issues
const LoginModal = dynamic(() => import("@/components/LoginModal"), { ssr: false });

type ChatMessage = {
    role: "user" | "model";
    text: string;
    isError?: boolean;
    retryText?: string;
};

const SUGGESTIONS = {
    en: [
        { icon: Dumbbell, text: "Best muscle building workout?" },
        { icon: Utensils, text: "Indian vegetarian protein?" },
        { icon: Zap, text: "How to reduce belly fat?" },
    ],
    hi: [
        { icon: Dumbbell, text: "Muscle badhane ki exercise?" },
        { icon: Utensils, text: "Veg protein foods kya hain?" },
        { icon: Zap, text: "Pet ki charbi kaise kam karein?" },
    ]
};

export default function TacticalChatbot() {
    const { isLoggedIn, user, remainingCredits, useCredit, refreshCredits, showWelcome, setShowWelcome } = useUserAuth();

    const [isOpen, setIsOpen] = useState(false);
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [input, setInput] = useState("");
    const [loading, setLoading] = useState(false);
    const [language, setLanguage] = useState<"en" | "hi" | null>(null);
    const [showLoginModal, setShowLoginModal] = useState(false);

    const scrollRef = useRef<HTMLDivElement>(null);
    const isDragging = useRef(false);
    const controls = useDragControls();

    const [position, setPosition] = useState({ bottom: "100px", right: "24px" });
    const [isLoaded, setIsLoaded] = useState(false);

    // Initialize position and load from storage safely
    useEffect(() => {
        setIsLoaded(true);
        const isMobile = window.innerWidth < 768;
        const defaultPos = isMobile ? { bottom: "80px", right: "24px" } : { bottom: "100px", right: "24px" };

        try {
            const saved = localStorage.getItem('brofit_chatbot_pos');
            if (saved) {
                const parsed = JSON.parse(saved);
                // Validate bounds (simple check) to prevent off-screen button
                const botVal = parseInt(parsed.bottom);
                const rightVal = parseInt(parsed.right);

                // If values are unreasonably large (off-screen) or negative, reset
                if (botVal > window.innerHeight - 50 || botVal < 0 || rightVal > window.innerWidth - 50 || rightVal < 0) {
                    setPosition(defaultPos);
                } else {
                    setPosition(parsed);
                }
            } else {
                setPosition(defaultPos);
            }
        } catch {
            setPosition(defaultPos);
        }
    }, []);

    const updatePosition = (info: PanInfo) => {
        if (typeof window !== 'undefined') {
            const newPos = {
                bottom: `${Math.max(20, window.innerHeight - info.point.y - 28)}px`,
                right: `${Math.max(20, window.innerWidth - info.point.x - 28)}px`
            };
            setPosition(newPos);
            localStorage.setItem('brofit_chatbot_pos', JSON.stringify(newPos));
        }
    };

    // Load language from localStorage on mount
    useEffect(() => {
        const saved = localStorage.getItem("brofit_chat_lang");
        if (saved === "en" || saved === "hi") {
            setLanguage(saved);
        }
    }, []);

    // Save language to localStorage when changed
    const handleLanguageChange = (newLang: "en" | "hi") => {
        setLanguage(newLang);
        localStorage.setItem("brofit_chat_lang", newLang);
    };

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages, language]);

    // Note: fetchRateLimit removed - now using user credits from useUserAuth

    useEffect(() => {
        if (isOpen && isLoggedIn) {
            refreshCredits();
        }
    }, [isOpen, isLoggedIn, refreshCredits]);

    // Welcome Popup for new users
    useEffect(() => {
        if (showWelcome) {
            // Show a temporary message
            setMessages(prev => [...prev, {
                role: "model",
                text: "Welcome to BroFit AI! You have 5 FREE AI credits for today. Credits reset daily at midnight.",
                isError: false
            }]);
            setIsOpen(true);
            
            // Clear the flag after handling
            const timer = setTimeout(() => setShowWelcome(false), 5000);
            return () => clearTimeout(timer);
        }
    }, [showWelcome, setShowWelcome]);

    // Calculate stroke dash for credit ring
    // 5 credits = 100%, 0 credits = 0%
    const radius = 22;
    const circumference = 2 * Math.PI * radius;
    const progress = remainingCredits / 5;
    const strokeDashoffset = circumference - (progress * circumference);
    
    // Google colors for the ring
    const getRingColor = () => {
        if (remainingCredits >= 4) return "#0F9D58"; // Green
        if (remainingCredits === 3) return "#4285F4"; // Blue
        if (remainingCredits === 2) return "#F4B400"; // Yellow
        if (remainingCredits <= 1) return "#DB4437"; // Red
        return "#DB4437";
    };

    const handleSend = async (text: string) => {
        if (!text.trim()) return;

        // Check if user is logged in
        if (!isLoggedIn) {
            setShowLoginModal(true);
            return;
        }

        // Check if user has credits
        if (remainingCredits <= 0) {
            setMessages((prev) => [...prev, {
                role: "model",
                text: language === "hi"
                    ? "Aapke aaj ke AI credits khatam ho gaye. Kal phir koshish karein!"
                    : "You've used all 5 daily AI credits. Credits reset at midnight!",
                isError: true
            }]);
            return;
        }

        const userMsg: ChatMessage = { role: "user", text };
        setMessages((prev) => [...prev, userMsg]);
        setInput("");
        setLoading(true);

        try {
            const userId = localStorage.getItem('brofit_user_id') || 'unknown';
            const res = await fetch("/api/chat", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "x-brofit-user-id": userId
                },
                body: JSON.stringify({
                    message: text,
                    context: {
                        source: "floating_chat",
                        language: language || "en",
                        developer: "Anurag Mishra",
                        contact: "+91 91311 79343",
                        owner: "Anurag Mishra",
                        gym_name: "Brother's Fitness"
                    }
                }),
            });
            const data = await res.json();

            if (!res.ok) {
                // Add error message with retry capability
                setMessages((prev) => [...prev, {
                    role: "model",
                    text: data.error || (language === "hi" ? "Sampark toot gaya." : "Connection Severed."),
                    isError: true,
                    retryText: text
                }]);
            } else {
                setMessages((prev) => [...prev, { role: "model", text: data.response || (language === "hi" ? "Sampark toot gaya." : "Connection Severed.") }]);
                await useCredit(); // Deduct one credit after successful response
            }
        } catch {
            setMessages((prev) => [...prev, {
                role: "model",
                text: language === "hi" ? "System offline hai." : "Error: System Offline.",
                isError: true,
                retryText: text
            }]);
        } finally {
            setLoading(false);
        }
    };

    if (!isLoaded) return null; // Prevent hydration mismatch

    return (
        <>
            <AnimatePresence>
                {!isOpen && (
                    <motion.button
                        id="tactical-chatbot-button"
                        className="fixed z-[9999] w-12 h-12 min-[350px]:w-14 min-[350px]:h-14 bg-gym-red rounded-full flex items-center justify-center shadow-[0_0_20px_rgba(215,25,33,0.5)] border-2 border-transparent relative"
                        initial={{ scale: 0, opacity: 0, ...position }}
                        animate={{ scale: 1, opacity: 1, ...position }}
                        exit={{ scale: 0, opacity: 0, transition: { duration: 0.2 } }}

                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        drag
                        dragMomentum={false}
                        onDragStart={() => { isDragging.current = true; }}
                        onDragEnd={(_, info) => {
                            setTimeout(() => { isDragging.current = false; }, 100);
                            updatePosition(info);
                        }}
                        onClick={() => { if (!isDragging.current) setIsOpen(true); }}
                        whileDrag={{ scale: 1.2, cursor: "grabbing" }}
                        aria-label="Open BroFit AI chat"
                        tabIndex={0}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                setIsOpen(true);
                            }
                        }}
                    >
