                                                    <motion.div animate={{ scale: [1, 1.2, 1] }} transition={{ repeat: Infinity, duration: 0.6 }} className="w-1.5 h-1.5 bg-gym-red rounded-full" />
                                                    <motion.div animate={{ scale: [1, 1.2, 1] }} transition={{ repeat: Infinity, duration: 0.6, delay: 0.2 }} className="w-1.5 h-1.5 bg-gym-red rounded-full" />
                                                    <motion.div animate={{ scale: [1, 1.2, 1] }} transition={{ repeat: Infinity, duration: 0.6, delay: 0.4 }} className="w-1.5 h-1.5 bg-gym-red rounded-full" />
                                                </div>
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {/* Input */}
                                <form
                                    onSubmit={(e) => { e.preventDefault(); handleSend(input); }}
                                    className="p-3 border-t border-white/10 bg-black flex gap-2 cursor-auto"
                                    onPointerDownCapture={(e) => e.stopPropagation()}
                                >
                                    <button
                                        type="button"
                                        onClick={() => setLanguage(null)}
                                        className="p-2 text-gray-500 hover:text-white transition-colors"
                                        title="Change Language"
                                        aria-label="Change language"
                                    >
                                        <Languages className="w-5 h-5" />
                                    </button>
                                    <input
                                        value={input}
                                        onChange={(e) => setInput(e.target.value)}
                                        placeholder={language === "hi" ? "Poochhein..." : "Ask BroFit..."}
                                        className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-sm text-white focus:outline-none focus:border-gym-red transition-colors placeholder:text-gray-600"
                                    />
                                    <button
                                        type="submit"
                                        disabled={loading || !input.trim()}
                                        className="bg-gym-red p-2 rounded-xl text-white hover:bg-white hover:text-black disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                                        aria-label="Send message"
                                    >
                                        <Send className="w-5 h-5" />
                                    </button>
                                </form>
                            </>
                        )}
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Login Modal */}
            <LoginModal
                isOpen={showLoginModal}
                onClose={() => setShowLoginModal(false)}
                onSuccess={() => setShowLoginModal(false)}
            />
        </>
    );
}

"use client";

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';

interface TacticalSoundContextType {
    soundEnabled: boolean;
    toggleSound: () => void;
    playClick: () => void;
    playSuccess: () => void;
    playHover: () => void;
}

const TacticalSoundContext = createContext<TacticalSoundContextType | null>(null);

// Tiny base64 encoded sounds (< 5KB each) - mechanical clicks
const _SOUNDS = {
    click: 'data:audio/mp3;base64,SUQzBAAAAAAAI1RTU0UAAAAPAAADTGF2ZjU4Ljc2LjEwMAAAAAAAAAAAAAAA//tQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAWGluZwAAAA8AAAACAAABhgC7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7v/////////////////////////////////',
    success: 'data:audio/mp3;base64,SUQzBAAAAAAAI1RTU0UAAAAPAAADTGF2ZjU4Ljc2LjEwMAAAAAAAAAAAAAAA//tQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAWGluZwAAAA8AAAACAAABhgC7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7v/////////////////////////////////',
    hover: 'data:audio/mp3;base64,SUQzBAAAAAAAI1RTU0UAAAAPAAADTGF2ZjU4Ljc2LjEwMAAAAAAAAAAAAAAA//tQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAWGluZwAAAA8AAAACAAABhgC7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7u7v/////////////////////////////////'
};

export function TacticalSoundProvider({ children }: { children: ReactNode }) {
    const [soundEnabled, setSoundEnabled] = useState(false);
    const [audioContext, setAudioContext] = useState<AudioContext | null>(null);

    useEffect(() => {
        // Load preference from localStorage
        const saved = localStorage.getItem('tacticalSoundEnabled');
        setSoundEnabled(saved === 'true');
    }, []);

    const toggleSound = useCallback(() => {
        setSoundEnabled(prev => {
            const newValue = !prev;
            localStorage.setItem('tacticalSoundEnabled', String(newValue));
            return newValue;
        });
    }, []);

    const playSound = useCallback((type: keyof typeof _SOUNDS) => {
        if (!soundEnabled) return;

        try {
            // Create audio context on first interaction
            const ctx = audioContext || new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
            if (!audioContext) setAudioContext(ctx);

            // Create a simple oscillator for tactile feedback
            const oscillator = ctx.createOscillator();
            const gainNode = ctx.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(ctx.destination);

            // Different sounds for different actions
            if (type === 'click') {
                oscillator.frequency.setValueAtTime(800, ctx.currentTime);
                oscillator.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + 0.05);
                gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.05);
                oscillator.start(ctx.currentTime);
                oscillator.stop(ctx.currentTime + 0.05);
            } else if (type === 'success') {
                oscillator.frequency.setValueAtTime(600, ctx.currentTime);
                oscillator.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);
                gainNode.gain.setValueAtTime(0.1, ctx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
                oscillator.start(ctx.currentTime);
                oscillator.stop(ctx.currentTime + 0.1);
            } else if (type === 'hover') {
                oscillator.frequency.setValueAtTime(1200, ctx.currentTime);
                gainNode.gain.setValueAtTime(0.02, ctx.currentTime);
                gainNode.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.02);
                oscillator.start(ctx.currentTime);
                oscillator.stop(ctx.currentTime + 0.02);
            }
        } catch {
            // Silently fail on unsupported browsers
        }
    }, [soundEnabled, audioContext]);

    const playClick = useCallback(() => playSound('click'), [playSound]);
    const playSuccess = useCallback(() => playSound('success'), [playSound]);
    const playHover = useCallback(() => playSound('hover'), [playSound]);

    return (
        <TacticalSoundContext.Provider value={{ soundEnabled, toggleSound, playClick, playSuccess, playHover }}>
            {children}
        </TacticalSoundContext.Provider>
    );
}

export function useTacticalSound() {
    const context = useContext(TacticalSoundContext);
    if (!context) {
        // Return no-op functions if not wrapped in provider
        return {
            soundEnabled: false,
            toggleSound: () => { },
            playClick: () => { },
            playSuccess: () => { },
            playHover: () => { }
        };
    }
    return context;
}

import { createHmac } from 'crypto';

// Stateless token verification for serverless environments
// We use a simple HMAC signature based on the ADMIN_PASSWORD
// In production, you could add an expiration timestamp to the payload

function getSecret(): string {
    const secret = process.env.ADMIN_PASSWORD;
    if (!secret) {
        throw new Error('CRITICAL: ADMIN_PASSWORD environment variable is not set.');
    }
    return secret;
}

export function generateAdminToken(): string {
    const timestamp = Date.now().toString();
    const signature = createHmac('sha256', getSecret())
        .update(timestamp)
        .digest('hex');

    // The token is [timestamp].[signature]
    return `${timestamp}.${signature}`;
}

export function verifyAdminToken(token: string): boolean {
    if (!token || !token.includes('.')) return false;

    const [timestamp, signature] = token.split('.');

    // Optional: Add expiration check (e.g., 24 hours)
    const tokenTime = parseInt(timestamp);
    const now = Date.now();
    if (isNaN(tokenTime) || now - tokenTime > 24 * 60 * 60 * 1000) {
        return false;
    }

    const expectedSignature = createHmac('sha256', getSecret())
        .update(timestamp)
        .digest('hex');

    return signature === expectedSignature;
}

